// Daily challenges: the same board the addon picks (HatedTCGDaily.lua), worked out again here from the date, the
// character's level at its first kill that day and its faction. Both use the tables in daily_data.ts /
// HatedTCGDailyData.lua (generated by tools/tcg_daily.py) and the same arithmetic, so they always agree.
import { DAILY } from './daily_data.ts';

export type Dungeon = typeof DAILY.dungeons[number];
export type Task = typeof DAILY.tasks[number];

const daysFromCivil = (y: number, m: number, d: number) => {
  if (m <= 2) y -= 1;
  const era = Math.floor(y / 400), yoe = y - era * 400, mp = (m + 9) % 12;
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
};
const yearOf = (z: number) => {
  let y = 1970 + Math.floor(z / 365.2425);
  if (daysFromCivil(y, 1, 1) > z) y -= 1; else if (daysFromCivil(y + 1, 1, 1) <= z) y += 1;
  return y;
};
const sundayOnOrAfter = (z: number) => z + (7 - (z + 4) % 7) % 7;
// the Pacific day number (days since 1970-01-01, Pacific time) of a unix time
export function pacificDay(t: number) {
  const y = yearOf(Math.floor(t / 86400));
  const on = (sundayOnOrAfter(daysFromCivil(y, 3, 1)) + 7) * 86400 + 10 * 3600;
  const off = sundayOnOrAfter(daysFromCivil(y, 11, 1)) * 86400 + 9 * 3600;
  const shift = (t >= on && t < off) ? -7 * 3600 : -8 * 3600;
  return Math.floor((t + shift) / 86400);
}

function rng(seed: string) {
  let s = 7;
  for (const b of new TextEncoder().encode(seed)) s = (s * 31 + b) % 2147483646 + 1;
  return (n: number) => { s = (s * 48271) % 2147483647; return s % n; };
}
export function board(day: number, lvl: number, fac: string): { dungeon?: Dungeon; tasks: Task[] } {
  const r = rng(`hated-daily-${DAILY.version}|${day}|${lvl}|${fac}`);
  const pool = DAILY.dungeons.filter(d => lvl >= d.lo && lvl <= d.hi && (d.fac === '' || d.fac === fac));
  const out: { dungeon?: Dungeon; tasks: Task[] } = { tasks: [] };
  if (pool.length) out.dungeon = pool[r(pool.length)];
  const cand = DAILY.tasks.filter(t => lvl >= t.min);
  for (let k = 0; k < DAILY.perDay && cand.length; k++) out.tasks.push(cand.splice(r(cand.length), 1)[0]);
  return out;
}

export type Prog = Record<string, number>;
export const taskCount = (p: Prog, t: Task) => (t.kind === 'type' ? p['type:' + t.param] : p[t.kind]) || 0;
// a dungeon is cleared with enough of its bosses down AND enough verified kills inside that same instance
export function dungeonDone(p: Prog, d: Dungeon) {
  if ((p['boss:' + d.key] || 0) < d.bosses) return false;
  for (const k of Object.keys(p)) {
    const m = k.match(/^bmap:([^:]+):(\d+)$/);
    if (m && m[1] === d.key && (d.map == null || +m[2] === d.map) && (p['map:' + m[2]] || 0) >= DAILY.dungeonTrash) return true;
  }
  return false;
}
export { DAILY };
